import logo from './assets/calvin-hobbes.jpg';
import './App.css';
import { Routes, Route, Link } from 'react-router-dom';
import { AuthProvider, useAuth } from './contexts/AuthContext';
import LotrMap from './lotr/LotrMap';
import MediaReviews from './media/MediaReviews';
import ExerciseTracker from './exercise/ExerciseTracker';
import Login from './components/Login';
import Register from './components/Register';
import ProtectedRoute from './components/ProtectedRoute';

function Home() {
  return (
    <div className="App">
      <header className="App-header">
        <img src={logo} alt="calvin and hobbes" />
        <p>
          Testing GitHub Pages for Calvin Woods.
        </p>
      </header>
    </div>
  );
}

function Navigation() {
  const { user, signOut } = useAuth();

  return (
    <nav className="App-nav">
      <Link to=".">Home</Link>
      <Link to="lotr-map">LOTR Map</Link>
      <Link to="media-reviews">Media Reviews</Link>
      <Link to="exercise-tracker">Exercise Tracker</Link>
      {user ? (
        <button onClick={signOut} className="nav-logout-btn">
          Logout ({user.email})
        </button>
      ) : (
        <Link to="login">Login</Link>
      )}
    </nav>
  );
}

function AppContent() {
  return (
    <div>
      <Navigation />
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="lotr-map" element={<LotrMap />} />
        <Route path="media-reviews" element={<MediaReviews />} />
        <Route path="login" element={<Login />} />
        <Route path="register" element={<Register />} />
        <Route
          path="exercise-tracker"
          element={
            <ProtectedRoute>
              <ExerciseTracker />
            </ProtectedRoute>
          }
        />
      </Routes>
    </div>
  );
}

function App() {
  return (
    <AuthProvider>
      <AppContent />
    </AuthProvider>
  );
}

export default App;
